const openInvoiceDialog=async()=>{if(!selected.value?.pkid)return;invoiceCustomerName.value=selected.value.entityName||'';invoiceDialogVisible.value=true;loadingInvoiceCandidates.value=true;invoiceCandidates.value=[];selectedInvoiceDeliveries.value=[];invoiceNotes.value='';try{const{data}=await axios.get(`${import.meta.env.VITE_API_URL}/WebGetCompatibleSalesDeliveries/${selected.value.pkid}`);invoiceCandidates.value=data||[];selectedInvoiceDeliveries.value=invoiceCandidates.value.filter((item:any)=>item.pkid===selected.value.pkid);}catch(e:any){invoiceDialogVisible.value=false;toast.add({severity:'error',summary:'No se pueden agrupar los albaranes',detail:e.response?.data||'Inténtalo de nuevo.',life:4500});}finally{loadingInvoiceCandidates.value=false;}};
